1	import { Router } from "express";
2	import type { Request } from "express";
3	import type { Db } from "@paperclipai/db";
4	import {
5	  createIssueTreeHoldSchema,
6	  previewIssueTreeControlSchema,
7	  releaseIssueTreeHoldSchema,
8	} from "@paperclipai/shared";
9	import { validate } from "../middleware/validate.js";
10	import { heartbeatService, issueService, issueTreeControlService, logActivity } from "../services/index.js";
11	import { assertBoard, assertCompanyAccess, getActorInfo } from "./authz.js";
12	
13	const TREE_RUN_CANCELLATION_RESPONSE_WAIT_MS = 1_000;
14	
15	function errorToMessage(error: unknown) {
16	  return error instanceof Error ? error.message : String(error);
17	}
18	
19	async function waitForRunCancellationTasks(tasks: Promise<void>[]) {
20	  let timeout: ReturnType<typeof setTimeout> | null = null;
21	  try {
22	    await Promise.race([
23	      Promise.all(tasks),
24	      new Promise((resolve) => {
25	        timeout = setTimeout(resolve, TREE_RUN_CANCELLATION_RESPONSE_WAIT_MS);
26	      }),
27	    ]);
28	  } finally {
29	    if (timeout) clearTimeout(timeout);
30	  }
31	}
