33	export function issueTreeControlRoutes(db: Db) {
34	  const router = Router();
35	  const issuesSvc = issueService(db);
36	  const treeControlSvc = issueTreeControlService(db);
37	  const heartbeat = heartbeatService(db);
38	
39	  async function resolveRootIssue(req: Request) {
40	    const rootIssueId = req.params.id as string;
41	    const root = await issuesSvc.getById(rootIssueId);
42	    return root;
43	  }
44	
45	  router.post("/issues/:id/tree-control/preview", validate(previewIssueTreeControlSchema), async (req, res) => {
46	    assertBoard(req);
47	    const root = await resolveRootIssue(req);
48	    if (!root) {
49	      res.status(404).json({ error: "Root issue not found" });
50	      return;
51	    }
52	    assertCompanyAccess(req, root.companyId);
53	
54	    const preview = await treeControlSvc.preview(root.companyId, root.id, req.body);
55	    const actor = getActorInfo(req);
56	    await logActivity(db, {
57	      companyId: root.companyId,
58	      actorType: actor.actorType,
59	      actorId: actor.actorId,
60	      agentId: actor.agentId,
61	      runId: actor.runId,
62	      action: "issue.tree_control_previewed",
63	      entityType: "issue",
64	      entityId: root.id,
65	      details: {
66	        mode: preview.mode,
67	        totals: preview.totals,
68	        warningCodes: preview.warnings.map((warning) => warning.code),
69	      },
70	    });
71	
72	    res.json(preview);
73	  });
74	
75	  router.post("/issues/:id/tree-holds", validate(createIssueTreeHoldSchema), async (req, res) => {
76	    assertBoard(req);
77	    const root = await resolveRootIssue(req);
78	    if (!root) {
79	      res.status(404).json({ error: "Root issue not found" });
80	      return;
81	    }
82	    assertCompanyAccess(req, root.companyId);
83	
84	    const actor = getActorInfo(req);
85	    const actorInput = {
86	      actorType: actor.actorType,
87	      actorId: actor.actorId,
88	      agentId: actor.agentId,
89	      userId: actor.actorType === "user" ? actor.actorId : null,
90	      runId: actor.runId,
91	    };
92	    let result = await treeControlSvc.createHold(root.companyId, root.id, {
93	      ...req.body,
94	      actor: actorInput,
95	    });
96	    await logActivity(db, {
97	      companyId: root.companyId,
98	      actorType: actor.actorType,
99	      actorId: actor.actorId,
100	      agentId: actor.agentId,
101	      runId: actor.runId,
102	      action: "issue.tree_hold_created",
103	      entityType: "issue",
104	      entityId: root.id,
105	      details: {
106	        holdId: result.hold.id,
107	        mode: result.hold.mode,
108	        reason: result.hold.reason,
109	        totals: result.preview.totals,
110	        warningCodes: result.preview.warnings.map((warning) => warning.code),
111	      },
112	    });
113	
114	    const runCancellationTasks: Promise<void>[] = [];
115	    if (result.hold.mode === "pause" || result.hold.mode === "cancel") {
116	      const interruptedRunIds = [...new Set(result.preview.activeRuns.map((run) => run.id))];
117	      for (const heartbeatRunId of interruptedRunIds) {
118	        const cancellationTask = (async () => {
119	          try {
120	            await heartbeat.cancelRun(heartbeatRunId);
121	            await logActivity(db, {
122	              companyId: root.companyId,
123	              actorType: actor.actorType,
124	              actorId: actor.actorId,
125	              agentId: actor.agentId,
126	              runId: actor.runId,
127	              action: "issue.tree_hold_run_interrupted",
128	              entityType: "heartbeat_run",
129	              entityId: heartbeatRunId,
130	              details: {
131	                holdId: result.hold.id,
132	                rootIssueId: root.id,
133	                reason: result.hold.mode === "pause" ? "active_subtree_pause_hold" : "subtree_cancel_operation",
134	              },
135	            });
136	          } catch (error) {
137	            await Promise.resolve(logActivity(db, {
138	              companyId: root.companyId,
139	              actorType: actor.actorType,
140	              actorId: actor.actorId,
141	              agentId: actor.agentId,
142	              runId: actor.runId,
143	              action: "issue.tree_hold_run_interrupt_failed",
144	              entityType: "heartbeat_run",
145	              entityId: heartbeatRunId,
146	              details: {
147	                holdId: result.hold.id,
148	                rootIssueId: root.id,
149	                reason: result.hold.mode === "pause" ? "active_subtree_pause_hold" : "subtree_cancel_operation",
150	                error: errorToMessage(error),
151	              },
152	            })).catch(() => null);
153	          }
154	        })();
155	        runCancellationTasks.push(cancellationTask);
156	      }
157	
158	      const cancelledWakeups = await treeControlSvc.cancelUnclaimedWakeupsForTree(
159	        root.companyId,
160	        root.id,
161	        result.hold.mode === "pause"
162	          ? "Cancelled because an active subtree pause hold was created"
163	          : "Cancelled because a subtree cancel operation was applied",
164	      );
165	      for (const wakeup of cancelledWakeups) {
166	        await logActivity(db, {
167	          companyId: root.companyId,
168	          actorType: actor.actorType,
169	          actorId: actor.actorId,
170	          agentId: actor.agentId,
171	          runId: actor.runId,
172	          action: "issue.tree_hold_wakeup_deferred",
173	          entityType: "agent_wakeup_request",
174	          entityId: wakeup.id,
175	          details: {
176	            holdId: result.hold.id,
177	            rootIssueId: root.id,
178	            agentId: wakeup.agentId,
179	            previousReason: wakeup.reason,
180	          },
181	        });
182	      }
183	    }
184	
185	    if (result.hold.mode === "cancel") {
186	      const statusUpdate = await treeControlSvc.cancelIssueStatusesForHold(root.companyId, root.id, result.hold.id);
187	      await logActivity(db, {
188	        companyId: root.companyId,
189	        actorType: actor.actorType,
190	        actorId: actor.actorId,
191	        agentId: actor.agentId,
192	        runId: actor.runId,
193	        action: "issue.tree_cancel_status_updated",
194	        entityType: "issue",
195	        entityId: root.id,
196	        details: {
197	          holdId: result.hold.id,
198	          cancelledIssueIds: statusUpdate.updatedIssueIds,
199	          cancelledIssueCount: statusUpdate.updatedIssueIds.length,
200	        },
201	      });
202	    }
203	
204	    if (runCancellationTasks.length > 0) {
205	      await waitForRunCancellationTasks(runCancellationTasks);
206	    }
207	
208	    if (result.hold.mode === "restore") {
209	      let statusUpdate;
210	      try {
211	        statusUpdate = await treeControlSvc.restoreIssueStatusesForHold(root.companyId, root.id, result.hold.id, {
212	          reason: result.hold.reason,
213	          actor: actorInput,
214	        });
215	      } catch (error) {
216	        await treeControlSvc.releaseHold(root.companyId, root.id, result.hold.id, {
217	          reason: "Restore operation failed before subtree status updates completed",
218	          metadata: {
219	            cleanup: "restore_failed_before_apply",
220	          },
221	          actor: actorInput,
222	        }).catch(() => null);
223	        throw error;
224	      }
225	      if (statusUpdate.restoreHold) {
226	        result = { ...result, hold: statusUpdate.restoreHold };
227	      }
228	      await logActivity(db, {
229	        companyId: root.companyId,
230	        actorType: actor.actorType,
231	        actorId: actor.actorId,
232	        agentId: actor.agentId,
233	        runId: actor.runId,
234	        action: "issue.tree_restore_status_updated",
235	        entityType: "issue",
236	        entityId: root.id,
237	        details: {
238	          holdId: result.hold.id,
239	          restoredIssueIds: statusUpdate.updatedIssueIds,
240	          restoredIssueCount: statusUpdate.updatedIssueIds.length,
241	          releasedCancelHoldIds: statusUpdate.releasedCancelHoldIds,
242	        },
243	      });
244	
245	      const wakeAgents = typeof req.body.metadata === "object"
246	        && req.body.metadata !== null
247	        && (req.body.metadata as Record<string, unknown>).wakeAgents === true;
248	      if (wakeAgents) {
249	        for (const restoredIssue of statusUpdate.updatedIssues) {
250	          if (!restoredIssue.assigneeAgentId) continue;
251	          const wakeRun = await heartbeat
252	            .wakeup(restoredIssue.assigneeAgentId, {
253	              source: "assignment",
254	              triggerDetail: "system",
255	              reason: "issue_tree_restored",
256	              payload: {
257	                issueId: restoredIssue.id,
258	                rootIssueId: root.id,
259	                restoreHoldId: result.hold.id,
260	              },
261	              requestedByActorType: actor.actorType,
262	              requestedByActorId: actor.actorId,
263	              contextSnapshot: {
264	                issueId: restoredIssue.id,
265	                taskId: restoredIssue.id,
266	                wakeReason: "issue_tree_restored",
267	                source: "issue.tree_restore",
268	                rootIssueId: root.id,
269	                restoreHoldId: result.hold.id,
270	              },
271	            })
272	            .catch(() => null);
273	          if (!wakeRun) continue;
274	          await logActivity(db, {
275	            companyId: root.companyId,
276	            actorType: actor.actorType,
277	            actorId: actor.actorId,
278	            agentId: actor.agentId,
279	            runId: actor.runId,
280	            action: "issue.tree_restore_wakeup_requested",
281	            entityType: "heartbeat_run",
282	            entityId: wakeRun.id,
283	            details: {
284	              holdId: result.hold.id,
285	              rootIssueId: root.id,
286	              issueId: restoredIssue.id,
287	              agentId: restoredIssue.assigneeAgentId,
288	            },
289	          });
290	        }
291	      }
292	    }
293	
294	    res
295	      .status(result.hold.mode === "restore" || result.hold.mode === "resume" ? 200 : 201)
296	      .json(result);
297	  });
