299	  router.get("/issues/:id/tree-control/state", async (req, res) => {
300	    assertBoard(req);
301	    const issueId = req.params.id as string;
302	    const issue = await issuesSvc.getById(issueId);
303	    if (!issue) {
304	      res.status(404).json({ error: "Issue not found" });
305	      return;
306	    }
307	    assertCompanyAccess(req, issue.companyId);
308	    const activePauseHold = await treeControlSvc.getActivePauseHoldGate(issue.companyId, issue.id);
309	    res.json({ activePauseHold });
310	  });
311	
312	  router.get("/issues/:id/tree-holds", async (req, res) => {
313	    assertBoard(req);
314	    const root = await resolveRootIssue(req);
315	    if (!root) {
316	      res.status(404).json({ error: "Root issue not found" });
317	      return;
318	    }
319	    assertCompanyAccess(req, root.companyId);
320	    const statusParam = typeof req.query.status === "string" ? req.query.status : null;
321	    const modeParam = typeof req.query.mode === "string" ? req.query.mode : null;
322	    const includeMembers = req.query.includeMembers === "true";
323	    const holds = await treeControlSvc.listHolds(root.companyId, root.id, {
324	      status: statusParam === "active" || statusParam === "released" ? statusParam : undefined,
325	      mode:
326	        modeParam === "pause" || modeParam === "resume" || modeParam === "cancel" || modeParam === "restore"
327	          ? modeParam
328	          : undefined,
329	      includeMembers,
330	    });
331	    res.json(holds);
332	  });
333	
334	  router.get("/issues/:id/tree-holds/:holdId", async (req, res) => {
335	    assertBoard(req);
336	    const root = await resolveRootIssue(req);
337	    if (!root) {
338	      res.status(404).json({ error: "Root issue not found" });
339	      return;
340	    }
341	    assertCompanyAccess(req, root.companyId);
342	
343	    const hold = await treeControlSvc.getHold(root.companyId, req.params.holdId as string);
344	    if (!hold || hold.rootIssueId !== root.id) {
345	      res.status(404).json({ error: "Issue tree hold not found" });
346	      return;
347	    }
348	    res.json(hold);
349	  });
350	
351	  router.post(
352	    "/issues/:id/tree-holds/:holdId/release",
353	    validate(releaseIssueTreeHoldSchema),
354	    async (req, res) => {
355	      assertBoard(req);
356	      const root = await resolveRootIssue(req);
357	      if (!root) {
358	        res.status(404).json({ error: "Root issue not found" });
359	        return;
360	      }
361	      assertCompanyAccess(req, root.companyId);
362	
363	      const actor = getActorInfo(req);
364	      const hold = await treeControlSvc.releaseHold(root.companyId, root.id, req.params.holdId as string, {
365	        ...req.body,
366	        actor: {
367	          actorType: actor.actorType,
368	          actorId: actor.actorId,
369	          agentId: actor.agentId,
370	          userId: actor.actorType === "user" ? actor.actorId : null,
371	          runId: actor.runId,
372	        },
373	      });
374	      await logActivity(db, {
375	        companyId: root.companyId,
376	        actorType: actor.actorType,
377	        actorId: actor.actorId,
378	        agentId: actor.agentId,
379	        runId: actor.runId,
380	        action: "issue.tree_hold_released",
381	        entityType: "issue",
382	        entityId: root.id,
383	        details: {
384	          holdId: hold.id,
385	          mode: hold.mode,
386	          reason: hold.releaseReason,
387	          memberCount: hold.members?.length ?? 0,
388	        },
389	      });
390	
391	      res.json(hold);
392	    },
393	  );
394	
395	  return router;
396	}
